import{_ as a,o as i,c as r,ai as t}from"./chunks/framework.ampVZV4B.js";const _=JSON.parse('{"title":"Node.js 面试 · 基础与事件循环","description":"","frontmatter":{},"headers":[],"relativePath":"guide/nodejs/basics-interview.md","filePath":"guide/nodejs/basics-interview.md"}'),o={name:"guide/nodejs/basics-interview.md"};function d(l,e,s,c,n,h){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="node-js-面试-·-基础与事件循环" tabindex="-1">Node.js 面试 · 基础与事件循环 <a class="header-anchor" href="#node-js-面试-·-基础与事件循环" aria-label="Permalink to “Node.js 面试 · 基础与事件循环”">​</a></h1><hr><h2 id="高频问法" tabindex="-1">高频问法 <a class="header-anchor" href="#高频问法" aria-label="Permalink to “高频问法”">​</a></h2><ol><li>Node.js 架构大概是怎样的？</li><li>事件循环阶段（口述版即可）？</li><li><code>process.nextTick</code>、<code>setImmediate</code>、<code>setTimeout</code> 差别？</li><li>Buffer 是什么？</li><li>Stream 解决什么问题？</li><li>CommonJS / ESM 混用坑？</li><li>全局对象和模块缓存？</li></ol><hr><h2 id="口述参考" tabindex="-1">口述参考 <a class="header-anchor" href="#口述参考" aria-label="Permalink to “口述参考”">​</a></h2><h3 id="_1-架构-简版" tabindex="-1">1）架构（简版） <a class="header-anchor" href="#_1-架构-简版" aria-label="Permalink to “1）架构（简版）”">​</a></h3><p>JS 代码跑在 V8；IO 等多靠底层线程池/系统能力，通过事件循环把结果回调回 JS 线程。<br> 一句话：<strong>单线程执行 JS + 非阻塞 IO。</strong></p><h3 id="_2-事件循环-面试够用版" tabindex="-1">2）事件循环（面试够用版） <a class="header-anchor" href="#_2-事件循环-面试够用版" aria-label="Permalink to “2）事件循环（面试够用版）”">​</a></h3><p>每个循环处理到期定时器、IO 回调、check（setImmediate）等阶段；微任务（Promise）会在阶段之间优先清空。<br> 不必背完整阶段名，但要懂：<strong>同步代码先跑完，再处理队列；长时间同步会卡死一切回调。</strong></p><h3 id="_3-nexttick-setimmediate-settimeout" tabindex="-1">3）nextTick / setImmediate / setTimeout <a class="header-anchor" href="#_3-nexttick-setimmediate-settimeout" aria-label="Permalink to “3）nextTick / setImmediate / setTimeout”">​</a></h3><ul><li><code>nextTick</code>：当前操作后尽快（微任务队列，优先很高）</li><li><code>setTimeout(fn, 0)</code>：进定时器队列，尽快但受循环阶段影响</li><li><code>setImmediate</code>：check 阶段</li></ul><p>实战少纠结精确顺序；原则是<strong>别用 nextTick 递归把 IO 饿死</strong>。</p><h3 id="_4-buffer" tabindex="-1">4）Buffer <a class="header-anchor" href="#_4-buffer" aria-label="Permalink to “4）Buffer”">​</a></h3><p>处理二进制数据（文件、TCP）。注意编码 <code>utf8</code>；拼接与长度；避免把巨大 Buffer 无脑转字符串占内存。</p><h3 id="_5-stream" tabindex="-1">5）Stream <a class="header-anchor" href="#_5-stream" aria-label="Permalink to “5）Stream”">​</a></h3><p>流式读写，管道 <code>pipe</code>/<code>pipeline</code>，适合大文件拷贝、上传下载，降低内存峰值。</p><h3 id="_6-模块系统" tabindex="-1">6）模块系统 <a class="header-anchor" href="#_6-模块系统" aria-label="Permalink to “6）模块系统”">​</a></h3><p>老项目 CJS 多；新项目 ESM。<br> TS 的 <code>module</code>/<code>moduleResolution</code> 配错会「本地能跑 CI 挂」。<br> 互操：知道 ESM 里加载 CJS 的常见限制即可。</p><h3 id="_7-模块缓存" tabindex="-1">7）模块缓存 <a class="header-anchor" href="#_7-模块缓存" aria-label="Permalink to “7）模块缓存”">​</a></h3><p><code>require</code> 同一路径会缓存实例；改配置热更新要注意清缓存或重启进程——Electron 开发时也常见。</p><hr><h2 id="追问预备" tabindex="-1">追问预备 <a class="header-anchor" href="#追问预备" aria-label="Permalink to “追问预备”">​</a></h2><ul><li>「Node 能写 CPU 密集？」→ 能但不适合主力；可 <code>worker_threads</code> 或外部服务。</li><li>「集群？」→ <code>cluster</code> 多进程利用多核；桌面端少用，服务端才常见。</li></ul>',24)])])}const f=a(o,[["render",d]]);export{_ as __pageData,f as default};
